const { useState } = React;

const COURSES = [
  { id: 1, name: '리액트 입문', hours: 8 },
  { id: 2, name: 'CSS 레이아웃', hours: 6 },
  { id: 3, name: '자바스크립트 기초', hours: 12 },
];

function App() {
  const [openId, setOpenId] = useState(null);

  if (openId !== null) {
    const course = COURSES.find((c) => c.id === openId);
    return (
      <div>
        <button className="back" type="button" onClick={() => setOpenId(null)}>목록으로</button>
        <p className="state">{course.name}</p>
        <p className="course">{course.hours}시간</p>
      </div>
    );
  }


  return (
    <div>
      <p className="state">코스 {COURSES.length}개</p>
      {COURSES.map((c) => (
        <p className="course" key={c.id}>
          {c.name}{' '}
          <button className="open" type="button" onClick={() => setOpenId(c.id)}>자세히</button>
        </p>
      ))}
    </div>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<App />);

